INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1770280979586, 'DSP/AMP', 'PXE-X120-10DP', '12CH DSP Amplifier', '장착 공임 별도/20만원 부터', 1900000, 'assets/images/DSP-X120-10DP.jpg', '[{"id":1770280583057.9543,"type":"text","value":"Frequency response : 20Hz~20kHz\nResolution: 1Hz\n\nInputs \n12 Ch Hi-Level / 2-Ch RCA Bluetooth / Optical / Coaxial [Hi-Level Input 30Vpp]\n\nOutputs \n10 Ch Hi-Level / 2 Ch RCA \n50W max x 1ch~4ch \n100W max x 5ch~10ch\nBridging 400W MAX x 9Ch~10Ch (4Ω)\n\nSampling Rate : 48KHz /24Bit\n\nSound & Tuning \n31-Band Parametric or Graphic EQ HPF /LPF / Bandpass Crossover per channel PC Application Matrix input summing\n\nDimension 250mm x 234mm x 50mm"},{"id":1770280936940.7808,"type":"image","value":"assets/images/DSP-X120-10DP-01.jpg"},{"id":1771487103960.264,"type":"text","value":"알파인의 PXE-X120-10DP는 현존하는 일체형 DSP 앰프 중 **''다채널 시스템의 끝판왕''**이라 불리는 모델입니다.\n\n10채널의 강력한 출력을 더해 복잡한 시스템을 단 한 대로 끝낼 수 있도록 설계된 마스터피스입니다.\n\n1. 10채널 고출력 & 12채널 프로세싱\n가장 큰 차별점은 역시 **10채널의 정격 출력(50W x 10)**입니다.\n\n보통 8채널 DSP로는 프런트 3-Way(6채널)를 구성하고 나면 리어 스피커나 센터 스피커를 포기해야 하는 경우가 많습니다.\n\n하지만 10DP는 프런트 3-Way + 리어 2-Way 또는 프런트 3-Way + 리어 + 센터 + 서브우퍼까지 외부 앰프 없이 단 한 대로 구동할 수 있습니다.\n\n\n2. 64-bit / 295MHz의 초정밀 연산\nX120 시리즈의 상징인 64비트 더블 프리시전 DSP를 탑재했습니다.\n\n채널 수가 많아질수록 위상(Phase) 관리가 기하급수적으로 어려워지는데, 이 모델은 초정밀 연산을 통해 10개 채널 소리의 도달 시간을 완벽하게 일치시켜, 마치 대시보드 위에 가수가 서 있는 듯한 **압도적인 정위감(Imaging)**을 만들어냅니다.\n\n\n3. 강화된 다이내믹 레인지와 전원부\n10개의 채널을 동시에 밀어주기 위해 설계된 전용 전원부는 일반적인 DSP 앰프와 궤를 달리합니다.\n\n100dB 이상의 높은 S/N비와 더불어, 고해상도 음원(Hi-Res) 재생 시 미세한 숨소리까지 잡아내는 디테일이 일품입니다.\n\n4. 시스템 단순화의 미학\n여러 대의 앰프와 DSP를 복잡하게 배선할 필요가 없습니다. 이는 설치 공간을 절약할 뿐만 아니라, 배선 간섭으로 인한 노이즈 발생 가능성을 원천적으로 차단하는 효과를 가져옵니다.\n\n5. PXE-X120-10DP는 스피커 개수가 많고, 시스템의 완성도를 극한으로 끌어올려야 하는 환경에 최적입니다.\n\n - 순정 10~12 스피커 시스템 차량: 보스(BOSE), 렉시콘(Lexicon), 메리디안(Meridian) 등 순정 스피커가 이미 다채널로 구성된 차량의 완벽한 1:1 대체 및 업그레이드.\n\n - 본격적인 ''풀 시스템'' 구축: 센터 스피커를 살리면서 프런트 3-Way와 리어까지 모두 독립 튜닝하려는 하이엔드 유저.\n\n - 쇼퍼 드리븐(Chauffeur-driven) 차량: 운전석뿐만 아니라 뒷좌석(VIP석) 사운드까지 정밀하게 튜닝해야 하는 대형 세단 및 리무진.\n\n6. 추천 차종 예시\n\n - 플래그십 SUV/세단: 제네시스 G90/GV80(렉시콘 팩), 랜드로버 레인지로버, 벤츠 S클래스/GLS.\n\n - 대형 MPV: 기아 카니발(하이리무진), 현대 스타리아 등 공간이 넓어 다채널 튜닝의 효과가 극대화되는 차량.\n\n - KGM 최상위 프로젝트: 액티언(Q300) 또는 향후 출시될 대형 전기차 라인업에서 최고 등급의 사운드 옵션을 구현할 때."},{"id":1771488309073.1062,"type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/PXE-X120-10DP-001.jpg"}]'::jsonb, '[{"id":1770281144548,"name":"PXE-X120-10DPCHOM-English","url":"assets/files/PXE-X120-10DPCHOM-English.pdf"}]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1770281132274, 'DSP/AMP', 'PXE-X121-12EV', '12CH DSP Amplifiler', '장착 공임 별도/20만원 부터', 2300000, 'assets/images/DSP-12EV.jpg', '[{"id":1770281213662.722,"type":"text","value":"Frequency response 20Hz~40kHz\n\nInputs \n12 Ch Hi-Level / 2-Ch RCA HD Bluetooth/ Optical / Coaxial/ USB (DAC) [Hi-Level Input 30Vpp]\n\nOutputs \n10 Ch Hi-Level\n2 Ch RCA \n10W max x 1CH~6CH\n50W max x 7CH~10CH\n200W max x 11ch~12ch(2Ω)\nSampling Rate : 48kHz/24Bit\n\nSound & Tuning \n31-Band Parametric or Graphic EQ HPF /LPF / Bandpass Crossover per channel Software PC\nMatrix input summing\n\nDimension 263mm x 262mm x 58mm"},{"id":1770281397528.0547,"type":"image","value":"assets/images/DSP-12EV-01.jpg"},{"id":1771488370740.3718,"type":"text","value":"알파인의 PXE-X121-12EV는 모델명에서 알 수 있듯, **''전기차(EV) 시대''**와 **''다채널 서라운드 시스템''**에 완벽하게 대응하기 위해 태어난 최첨단 플래그십 DSP 앰프입니다.\n\n12채널의 독립 출력을 제공하는 하이엔드 오디오의 완성형 모델입니다.\n\n1. ''12채널'' 독립 제어의 마법\n이 제품의 가장 큰 무기는 **12채널의 강력한 정격 출력(50W x 10 + 150W x 2 또는 유사 구성)**입니다.\n\n보통의 DSP가 리어나 서브우퍼에서 타협을 봐야 했다면, 이 모델은 **프런트 3-Way(6ch) + 리어(2ch) + 센터(1ch) + 서브우퍼(2ch)**라는 자동차 오디오의 ''풀 스펙''을 단 한 대의 기기로 완벽하게 구동합니다.\n\n2. 전기차(EV) 맞춤형 저전력 고효율 설계\n전기차 유저들이 가장 걱정하는 것이 ''배터리 소모''와 ''전기적 노이즈''입니다.\n\n121-12EV는 고효율 Class-D 증폭 기술을 극대화하여, 압도적인 채널 수와 출력을 자랑하면서도 소모 전력을 치밀하게 관리합니다. 또한 전기차 특유의 고주파 노이즈를 차단하는 필터 설계가 강화되어 매우 정숙한 배경음을 제공합니다.\n\n3. 하이레졸루션(Hi-Res) 오디오의 정점\n96kHz / 24bit 샘플링을 지원하며, 64비트 더블 프리시전 DSP 연산을 통해 음원 손실을 최소화합니다. 특히 최신 코덱인 aptX HD와 LDAC(지원 모델 확인 필요) 등 고해상도 블루투스 입력을 지원해 스마트폰만으로도 무선 하이파이 환경을 구축할 수 있습니다.\n\n4. 지능형 사운드 스테이지 복원\n최신 차량들의 복잡한 순정 오디오 신호를 분석하여, 사라진 저역대를 복원하거나 뒤틀린 위상을 바로잡는 **''지능형 매트릭스 알고리즘''**이 탑재되었습니다. 이는 순정 인포테인먼트 시스템을 그대로 사용하면서도 소리만 하이엔드로 바꾸고 싶은 유저들에게 축복과도 같은 기능입니다.\n\n5. PXE-X121-12EV는 단순한 업그레이드를 넘어, 시스템 전체를 재설계하려는 환경에 최적입니다.\n\n - 순정 스피커가 12개 이상인 고급형 차량: 앰프 채널이 부족해 스피커 몇 개를 죽여야 했던 고민을 완전히 해결해 줍니다.\n\n - 공간 효율이 중요한 최신 차량: 12채널 앰프 시스템을 개별로 구축하면 트렁크가 꽉 차지만, 이 모델은 컴팩트한 사이즈로 시트 아래나 측면 트림 안에 깔끔하게 매립할 수 있습니다.\n\n - 전기차 및 하이브리드: 배터리 효율이 중요하면서도 실내가 조용해 작은 노이즈도 거슬리는 차량들.\n\n6. 추천 차종 예시\n\n - 전기차 라인업: 테슬라 모델 3/Y(프리미엄 오디오 사양), 현대 아이오닉 5/6, 기아 EV6/EV9.\n\n - 다채널 수입차: 벤츠 S클래스/E클래스(부메스터 사양), BMW X5/X7(하만카돈 사양), 볼보(B&W 사양).\n\n - 국산 프리미엄: **KGM 액티언(Q300)**의 최상위 오디오 옵션이나 제네시스 시리즈처럼 스피커가 도처에 배치된 차량.\n\n\n12채널을 모두 사용하는 시스템에서는 스피커의 위치와 지향각이 무엇보다 중요합니다.\n특히 프런트 도어와 대시보드에 위치한 스피커들을 위해 알루미늄 가이드나 3D 프린팅(ABS 등)을 활용한 커스텀 마운트를 제작해 보세요. 물리적으로 정돈된 환경에 121-12EV의 64비트 프로세싱이 더해지면, 차 안은 더 이상 이동 수단이 아니라 완벽한 ''이동식 청음실''이 됩니다.\n\n또한, 12채널의 높은 대역폭을 감당하기 위해 순정 배선보다는 고품질 OFC(무산소동선) 배선 작업을 병행하는 것이 기기의 성능을 100% 끌어내는 핵심입니다."},{"id":1771488882007.2686,"type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/PXE-X121-12EV-001.jpg"}]'::jsonb, '[{"id":1770281131212,"name":"PXE-X120-10DPCHOM-English","url":"assets/files/PXE-X121-12EV.pdf"}]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1770281847783, 'DSP/AMP', 'PXE-X121-12EV x 2', '24CH DSP Amplifier _ 브릿지 케이블 포함', '장착 공임 별도/40만원 부터', 4750000, 'assets/images/DSP-12EVx2.jpg', '[{"id":1770281710535.6543,"type":"text","value":"Frequency response 20Hz~40kHz\n\nInputs\n24 Ch Hi-Level / 4-Ch RCA HD Bluetooth/ 2 Optical / 2 Coaxial/ 2 USB (DAC) [Hi-Level Input 30Vpp]\n\nOutputs\n20 Ch Hi-Level\n2 Ch RCA\n10W max x 1CH~6CH\n50W max x 7CH~10CH\n200W max x 11ch~12ch(2Ω)\n10W max x 13CH~18CH\n50W max x 19CH~22CH\n200W max x 23ch~24ch(2Ω)\nSampling Rate : 48kHz/24Bit\n4 Ch RCA\n\nSound & Tuning\n31-Band Parametric or Graphic EQ HPF /LPF / Bandpass Crossover per channel Software PC\nMatrix input summing"},{"id":1770281836365.4246,"type":"image","value":"assets/images/DSP-12EV-01.jpg"},{"id":1771489018224.1558,"type":"text","value":"알파인(Alpine)의 PXE-X121-12EV를 2개 연결하여 24채널 시스템을 구성하는 것은, 현존하는 카오디오 튜닝 중 가장 화려하고 압도적인 ''울트라 하이엔드'' 영역에 발을 들이는 것입니다.\n\n단순히 소리가 커지는 것을 넘어, 차량 내의 모든 스피커를 하나하나 독립적으로 완벽하게 통제하겠다는 의지가 담긴 구성이죠. 이 시스템의 특징과 가치를 알기 쉽게 설명해 드릴게요.\n\n1. 24채널 시스템의 핵심: \"듀얼 링크(Dual Link)\"\nPXE-X121-12EV는 설계 단계부터 **2대 연결(Linking)**을 고려하여 만들어졌습니다. 전용 링크 케이블로 두 기기를 연결하면 다음과 같은 마법이 일어납니다.\n\n소스 공유 (Source Sharing): 마스터(Master) 기기에 연결된 블루투스, 광학(Optical), 동축(Coaxial), USB 오디오 신호가 슬레이브(Slave) 기기로 무손실 공유됩니다. 소스 기기를 따로따로 연결할 필요가 없습니다.\n\n통합 제어: 24개의 채널을 하나의 시스템처럼 관리할 수 있습니다. 입력 매트릭스 설정이 동기화되어, 복잡한 다채널 신호 처리가 훨씬 간결해집니다.\n\n완벽한 독립 튜닝: 24개 스피커 각각에 대해 독립적인 31밴드 EQ, 타임 얼라이먼트, 크로스오버를 설정할 수 있습니다.\n\n2. 진정한 3D 서라운드 (Atmos급 환경) 구현\n최신 프리미엄 차량들은 스피커가 20개 이상인 경우가 많습니다.\n\n헤드라이너(천장) 스피커, A필러 상단의 하이트(Height) 스피커, 뒷좌석 서라운드까지 모든 유닛을 독립 제어하려면 24채널이 필수입니다. 소리가 위에서 아래로, 뒤에서 앞으로 흐르는 입체감을 완벽히 재현할 수 있습니다.\n\n3. ''1 스피커 = 1 채널'' 원칙의 실현\n스피커 배선을 브릿지로 묶지 않고 모든 드라이버에 전용 채널을 할당합니다.\n\n이를 통해 각 스피커의 물리적 특성에 맞는 초정밀 커팅이 가능해져, 중복되는 주파수로 인한 지저분한 소리(Phase Cancellation)를 원천 차단합니다.\n\n4. 압도적인 총 출력 (Total 1700W RMS 이상)\n단일 기기로는 부족할 수 있는 에너지를 두 배로 확보합니다. 특히 X121-12EV 특유의 스태거드 출력(Staggered Power) 설계를 24채널로 확장하면, 프런트 3-Way는 물론 리어와 서브우퍼까지 넘치는 힘으로 밀어줄 수 있습니다.\n\n5. 이 구성은 **\"공간이 넓고 스피커 배치가 복잡한 프리미엄 전기차 및 SUV\"**를 위해 존재합니다.\n\n - 테슬라 모델 X / 루시드 에어: 스피커 개수가 매우 많고 전력 효율이 중요한 전기차에서 최상의 궁합을 보여줍니다.\n\n - 럭셔리 풀사이즈 SUV: 에스컬레이드, 레인지로버, KGM 렉스턴급 차량처럼 실내 체적이 커서 다채널 배치의 효과가 극대화되는 경우.\n\n - 쇼카(Show Car) 및 데모카: 브랜드를 대표하는 최상위 사운드 퀄리티를 보여주어야 하는 프로젝트.\n\n\nPXE-X121-12EV 2대 구성은 **\"차 안에서 구현 가능한 물리적 사운드의 한계에 도전하는 일\"**입니다. KGM Q300 프로젝트가 차량 전체를 아우르는 압도적인 서라운드 시스템을 지향한다면, 이 24채널 구성이 가장 완벽한 마침표가 될 것입니다."}]'::jsonb, '[{"id":1770281684195,"name":"PXE-X121-12EV","url":"assets/files/PXE-X121-12EV.pdf"}]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1770334515662, 'Alpine Status', 'KTX-990', 'HDS-990의 컨트롤러 연장 케이블(2.5m 추가 연장용)', '', 70000, 'https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/KTX-990.jpg', '[]'::jsonb, '[]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1770334880774, 'DSP/AMP', 'PXE-C80-88', 'OPTIM8 8CH DSP Amplifier_컨트롤러 포함', '장착 공임 별도/20만원 부터', 1800000, 'assets/images/DSP-C80.jpg', '[{"id":"1770335301938.6367","type":"text","value":"8-Channel Hi-Res (96kHz/24Bit) Digital Sound Processor with Built-in Internal Amplifier\nRemove the Complexities of Sound Tuning with Simple, Self-Guided Auto-EQ Software via iOS App (iPhone / iPad) or PC App with External Mic Kit (sold seperately)\nAnti-EQ for OEM Systems (Eliminates Factory EQ Curve)\n8-Channel High-Level / 6-Channel RCA Audio Signal / Bluetooth® Audio Input\nOutputs: 8-Channel 4V RCA\n31 Band Parametric & Graphic EQ, Time Correction on all 8 Channels\nDigital Inputs: Coaxail, USB(DAC)\nSpeaker Input: Up to 30V (26Vpp)\nBuilt-in 8-Channel Amplifier: \n50W x 6@ 4Ω + 150W x 2 @ 4Ω or 50W x 6 @ 2Ω + 300W x 2 @ 2Ω\nDimensions: 23.4cm(W) x 24.2cm(H) x 5.1cm(D)"},{"id":"1770335532967.8804","type":"image","value":"assets/images/DSP-C80-02.jpg"},{"id":"1771572087949.2058","type":"text","value":"알파인(Alpine)의 **PXE-C80-88 (OPTIM8™)**은 복잡한 카오디오 튜닝 과정을 혁신적으로 단순화하면서도 하이엔드급 음질을 제공하는 8채널 DSP 일체형 앰프입니다.\n\n1. 올인원 솔루션 (8채널 DSP + 앰프): 별도의 프로세서와 앰프를 복잡하게 연결할 필요 없이, 단일 기기로 8채널의 스피커 출력을 제어합니다. (정격 출력: 50W x 6채널 + 150W x 2채널 @ 4Ω)\n\n\n2. Hi-Res Audio 인증: 96kHz/24bit의 고해상도 오디오 재생을 지원하여, 스튜디오 급의 선명한 사운드를 재현합니다.\n\n\n3. 강력한 순정 통합 기능 (Anti-EQ): 최신 차량의 순정 오디오에 걸려 있는 복잡한 EQ 값을 초기화(Flatten)하는 Anti-EQ 기능이 있어, 순정 헤드유닛을 그대로 사용하면서도 왜곡 없는 소리를 만들어냅니다\n\n\n4. PXE-C80-88은 특히 다음과 같은 상황에서 최고의 효율을 보여줍니다.\n\n  - 순정 인포테인먼트 시스템을 유지해야 하는 최신 차량\n최근 차량들은 내비게이션, 차량 설정 등이 헤드유닛에 통합되어 있어 오디오 교체가 거의 불가능합니다. PXE-C80-88은 순정 신호를 그대로 받아 하이엔드 사운드로 업그레이드하려는 차주분들에게 최적입니다.\n\n추천 차종: 국산 프리미엄 세단(제네시스 등), SUV(팰리세이드, 쏘렌토 등), 최신 수입차 라인업.\n\n  - 공간 활용이 중요한 소형/중형 차량\n별도의 앰프 랙을 짜기 부담스러운 소형 SUV나 해치백 차량에 적합합니다. 본체 하나로 전방 3-Way 스피커와 서브우퍼까지 구동할 수 있어 공간 손실을 최소화할 수 있습니다.\n\n  - 멀티 스피커 시스템(3-Way + Sub) 구성 시\n전면 트위터, 미드레인지, 미드우퍼를 각각 독립적으로 제어하는 프론트 3-Way 구성과 서브우퍼를 동시에 운용하고 싶을 때, 8개의 채널은 매우 여유로운 옵션이 됩니다. (7, 8번 채널의 높은 출력을 미드우퍼나 서브우퍼용으로 활용 가능)\n\n"}]'::jsonb, '[{"id":1770335066328,"name":"PXE-C80-88_manual","url":"assets/files/PXE-C80-88_manual.pdf"}]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1770337380170, 'DSP/AMP', 'R2-A60F', '4CH Amplifier', '장착 공임 별도/20만원 부터', 750000, 'assets/images/amp-a60f.jpg', '[{"id":1770337164724.3816,"type":"text","value":"FEATURES\nHi-Res Audio Certified (Up to 45kHz)\n4-Channel Amplifier\nAlpine’s Class D Amplifier Circuit\nReduced Footprint (15% smaller compared to the previous R-A60F model)\nOne-Sided Terminal Layout\nTop Panel Sound Controls\nIntegrated Mounting Feet for Simple Installation\nOptional Remote Bass Knob Compatible (required RUX-KNOB.2 or RUX-H01, sold separately)\n\n\nTECH SPECS\nDimensions: 28.2cm W x 5.6cm H x 16.6cm D\nPower Rating: 14.4V, ≤ 1% THD +N\nPower Output: 100W x 4 @ 4Ω, 150W x 4 @ 2Ω\nBridged Power: 300W x 2 @ 4Ω\nS/N Ratio: >80dB\nFrequency Response: 10Hz – 45kHz\nDamping Factor: >100\nCTA-2006-D Certification"}]'::jsonb, '[{"id":1770337462524,"name":"R-A60F_R-A75M_OM","url":"assets/files/R-A60F_R-A75M_OM.pdf"}]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1770337818950, 'DSP/AMP', 'S2-A60M', '600W Mono Amplifier', '장착 공임 별도/20만원 부터', 700000, 'assets/images/amp-a60m.jpg', '[{"id":1770337758690.3735,"type":"text","value":"Alpine’s Class D Amplifier Circuit\nBuilt-in Selectable / Adjustable Crossovers\nDimensions: 22.1cm(W) x 5.8cm(H) 21cm(D)\nFrequency Response: 10Hz - 400Hz\nS/N Ratio: >85dB\nPower Output: 330W x 1 @ 4Ω\n600W x 1 @ 2Ω\n600W x 1 @ 1Ω"}]'::jsonb, '[{"id":1770337640392,"name":"OM_S2-A60M_S2-A120M","url":"assets/files/OM_S2-A60M_S2-A120M.pdf"}]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1770338317503, 'DSP/AMP', 'PWE-M770', '7" Powered Subwoofer Box', '장착 공임 별도/20만원 부터', 360000, 'assets/images/amp-m770.jpg', '[{"id":1770338215560.4856,"type":"text","value":"Subwoofer Type\n7 x 7\" Powered Subwoofer Box\n\nFrequency response\n10 Hz - 150 Hz\n\nPower handling\n300 Watts peak power\nSensitivity 90dB\n\nDesign\nDurable Cast Metal Construction"},{"id":1770338309372.929,"type":"image","value":"assets/images/amp-m770-01.jpg"}]'::jsonb, '[{"id":1770338210722,"name":"PWE-M770-OM","url":"assets/files/PWE-M770-OM.pdf"}]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1770338439799, 'DSP/AMP', 'PWE-770-RCU', 'PWE-M770 컨트롤러', '.', 40000, 'assets/images/amp-m770rcu.jpg', '[]'::jsonb, '[]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1770339269599, 'Speakers', 'R2-S653', 'Pro 3-Way Component Speaker Set', '장착 공임 별도/20만원 부터', 1060000, 'assets/images/spk-r2653.jpg', '[{"id":1770339075465.8064,"type":"text","value":"FEATURES\nHi-Res Audio Certified\nGlass Fiber Reinforced Cone\nDie-Cast Aluminum Basket\nFerrite Magnet Structure\nHigh-Amplitude Multi-Roll (H.A.M.R.) Surround\n2 Premium-Grade Full Passive Performance Crossover Networks\nMagnesium Hard-Dome Tweeters with Swivel Mount Design and Threaded Removable Housing\nProtective Open Mesh Grille Pair Included\n\nWhat''s in the Box:\n(x2) 6.5\" Mid-Bass Speakers\n(x2) 3\" Mid-Range Speakers\n(x2) 1\" Tweeters (Component)\n(x2) 6.5\" Grilles\n(x2) 3\" Grilles\nMounting Hardware (x12 Screws, x12 Speed Clips)\nTweeter Hardware (x2 Locking Rings, x2 On-Dash Mounting)\nAlpine Registration Card\nAlpine Limited Warranty Sheet\nOwner''s Manual\nInstallation Guide\n\nTECH SPECS\nConfiguration: 6.5\" Mid-Bass + 3\" Mid-Range + 1\" Tweeter (Component)\n\nFrequency Response: 65Hz - 40kHz\n\nPower Handling: 300W Peak"},{"id":1770339168775.9648,"type":"text","value":"완전히 새로운 R-시리즈 프로(Pro) 스피커\n\nAlpine의 전설적인 R-시리즈 스피커가 3세대로 진화했습니다. 혁신적인 소재로 설계되어 더 강력한 출력과 놀라운 사운드를 선사합니다. 사용자의 예산과 원하는 음질에 맞춰 프로(Professional) 라인과 스탠다드(Standard) 라인 중 자유롭게 선택할 수 있습니다.\n\n음악을 크게 즐기며 그 존재감을 드러내고 싶다면, R-시리즈 스피커가 완벽한 해답이 될 것입니다. 왜곡 없이 크고 선명한 소리를 구현하며, **중앙 사운드 스테이지(Center Sound Stage)**의 깊이를 만끽할 수 있습니다. 특히 고역대와 저역대 주파수를 강조하도록 튜닝되어, 강력한 힘을 전달하면서도 밝고 생동감 넘치는 사운드를 자연스럽게 재생합니다. 또한, R-시리즈 서브우퍼 및 앰프와 함께 사용할 때 출력과 성능 면에서 최고의 궁합을 자랑합니다.\n\nR-시리즈 라인업은 모두 하이레졸루션 오디오(Hi-Res Audio) 인증을 받았으며, 최대 40kHz의 주파수 응답 범위를 지원합니다. 이번 R-시리즈에서는 최초로 3웨이(3-way) 시스템이 도입되었으며, 프로 라인과 스탠다드 라인 중에서 선택할 수 있는 폭이 더욱 넓어졌습니다."},{"id":1770339175906.996,"type":"image","value":"assets/images/spk-r2653-01.jpg"},{"id":1770339246475.6826,"type":"text","value":"3-웨이 컴포넌트 프로(PRO) 스피커\n\nR2-S653은 R-시리즈 스피커 라인업 중 최상위(Top of the line) 모델입니다. 이 시스템은 16.5cm 도어 우퍼, 9.6cm 미드레인지 스피커, 그리고 최대 40kHz의 초고역대 주파수 응답 범위를 지원하는 4.3cm 트위터로 구성되어 있습니다."},{"id":1770339290909.913,"type":"image","value":"assets/images/spk-r2653-02.jpg"},{"id":1770339314667.3552,"type":"text","value":"유리 섬유 강화 콘 (Glass-Fiber Reinforced Cone)\n\n도어 우퍼에는 완전히 새로워진 유리 섬유 강화 콘이 적용되었습니다. 이 소재는 강성이 매우 높으면서도 무게는 극도로 가벼워, 매우 빠른 응답 속도와 극도로 정밀한 음악 재생을 가능하게 합니다."},{"id":1770339355439.2966,"type":"image","value":"assets/images/spk-r2653-03.jpg"},{"id":1770339363101.9697,"type":"text","value":"복합 소재 바스켓 및 대형 마그넷\n\n스탠다드 모델(R2-S69C, R2-S65, R2-S69)은 프로(PRO) 모델에 적용된 알루미늄 다이캐스트 바스켓 대신 복합 소재(Composite) 바스켓을 채택하여, 더욱 합리적인 가격대를 실현했습니다. 또한, 이전 세대와 **동일한 설치 깊이(Mounting depth)**를 유지하면서도 더 거대한 마그넷을 탑재하여 성능을 강화했습니다."},{"id":1770339421665.893,"type":"image","value":"assets/images/spk-r2653-04.jpg"},{"id":1770339459686.3967,"type":"text","value":"하이레졸루션 오디오(Hi-Res Audio) 인증 하드 돔 트위터\n\n완전히 새로워진 마그네슘 하드 돔 트위터는 선명하고 디테일한 사운드를 재현하며, 최대 40kHz의 고주파수(하이레졸루션 오디오 표준)까지 재생할 수 있습니다.\n\n설치 시에는 나사선 구조의 하우징을 이용해 도어 패널 등에 **매립형(Flush-mount)**으로 깔끔하게 장착하거나, 기본 제공되는 대시보드용 마운트를 사용할 수 있습니다. 또한, 트위터는 하우징 내에서 자유롭게 **각도 조절(Swivel)**이 가능하여, 소리의 지향성을 사용자의 **스위트 스팟(최적의 청취 위치)**에 정확히 맞출 수 있습니다"},{"id":1770339517996.8179,"type":"image","value":"assets/images/spk-r2653-05.jpg"},{"id":1770339527840.921,"type":"text","value":"순정 위치에 최적화된 간편한 트위터 장착\n\nR-시리즈 트위터는 설치용 프레임과 트림 링을 간단히 분리할 수 있어, 전체 크기와 직경을 최소화할 수 있습니다. 프레임을 제거한 트위터 본체는 매우 콤팩트하여 차량 순정(OEM) 트위터 위치(A필러 내부, 사이드미러 삼각 커버, 도어 패널 등)에 대부분 그대로 들어갑니다. 덕분에 차량 내부 인테리어를 손상시키지 않고 깔끔하게 숨겨서 설치하는 **''스텔스(Stealth) 인스톨''**이 가능합니다."},{"id":1770339585796.312,"type":"image","value":"assets/images/spk-r2653-06.jpg"},{"id":1770339638404.142,"type":"text","value":"유연한 설정을 지원하는 프로급 크로스오버(X-Over) 네트워크\n\n이 대형 크로스오버 네트워크는 최고의 음질을 위해 엄선된 다수의 고품질 부품들로 구성되어 있습니다. 사용자의 청취 취향이나 차량 환경에 맞춰 미드레인지 스피커 레벨을 -3dB / 0dB / +3dB로 조절할 수 있으며, 트위터 레벨 또한 동일하게 -3dB / 0dB / +3dB 범위 내에서 세밀하게 조정이 가능합니다."},{"id":1770339698721.6926,"type":"image","value":"assets/images/spk-r2653-07.jpg"},{"id":1770339710498.9062,"type":"text","value":"HAMR 서라운드 (High-Amplitude Multi-Roll)\n\nAlpine 고유의 HAMR(고진폭 멀티롤) 서라운드 기술은 스피커 콘이 전후로 움직이는 폭(Excursion)을 최대화하면서도, 흔들림 없는 정밀한 제어력을 유지합니다. 그 결과, 볼륨을 크게 높여도 소리의 왜곡 없이 강력하고 깊은 저음을 구현합니다."}]'::jsonb, '[]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;